public boolean shouldPrintMessage(int timestamp, String message) {
    // Get the frequency for the message, defaulting to 10 if not set
    int frequency = frequencyMap.getOrDefault(message, 10);

    // Get the last print timestamp for the message, defaulting to -1 if not set
    int lastPrintTime = lastPrintMap.getOrDefault(message, -1);

    // Check if enough time has elapsed since the last print
    if (timestamp - lastPrintTime >= frequency) {
        // Update the last print time for this message
        lastPrintMap.put(message, timestamp);
        return true;
    }

    return false;
}

