public boolean remove(int val) {
        if (size == 0) {
            return false;
        }
        int index = val % capacity;
        while (used[index]) {
            if (keys[index] == val) {
                // Mark slot as free, but we need to re-insert subsequent elements
                // to avoid breaking probe chains.
                int backupIndex = index;
                int nextIndex = (index + 1) % capacity;
                keys[backupIndex] = 0;
                used[backupIndex] = false;
                size--;
                while (used[nextIndex]) {
                    int tmpKey = keys[nextIndex];
                    int rehash = tmpKey % capacity;
                    keys[nextIndex] = 0;
                    used[nextIndex] = false;
                    while (used[rehash]) {
                        rehash = (rehash + 1) % capacity;
                    }
                    keys[rehash] = tmpKey;
                    used[rehash] = true;
                    nextIndex = (nextIndex + 1) % capacity;
                }
                return true;
            }
            index = (index + 1) % capacity;
        }
        return false;
    }

