    // Generate a hash code for the value
    int hashCode = Math.abs(val % BUCKETS);

    // Traverse the linked list to check for duplicates
    for (Node node = table[hashCode]; node != null; node = node.next) {
        if (node.val == val) {
            return false;
        }
    }

    // Create a new Node and insert it at the head of the linked list
    Node newNode = new Node(val);
    newNode.next = table[hashCode];
    table[hashCode] = newNode;

    size++;

    // Check for rehashing if needed
    if (size > BUCKETS * LOAD_FACTOR) {
        rehash();
    }

    return true;
}

