            throw new IndexOutOfBoundsException("Constant pool entry index " + constantPoolEntryIndex + " is out of bounds.");
        }

        // A CONSTANT_Utf8 entry starts with a tag (0x01), followed by a 2-byte unsigned length, 
        // then the bytes of the modified UTF-8 encoded string.

        // Read the tag. It must be 0x01 for CONSTANT_Utf8.
        final int tag = classFileBuffer[constantPoolEntryIndex];
        if (tag != 0x01) {
            throw new RuntimeException("Invalid CONSTANT_Utf8 tag: " + tag + " at index " + constantPoolEntryIndex);
        }

        // The length field is the next 2 bytes (big-endian)
        final int length = ((classFileBuffer[constantPoolEntryIndex + 1] & 0xFF) << 8) | (classFileBuffer[constantPoolEntryIndex + 2] & 0xFF);

        // The UTF-8 data starts 3 bytes after the tag
        final int dataStartIndex = constantPoolEntryIndex + 3;

        // Protect against the length extending beyond the buffer
        if (dataStartIndex + length > classFileBuffer.length()) {
