        // Note: The length of the decoded string can be up to 'length' characters if it's all 1-byte ASCII,
        // but modified UTF-8 can have multi-byte sequences. So the final string length <= length.
        // However, a single modified UTF-8 byte sequence can represent one character, so the max chars is 'length'.
        if (charBuffer.length < length) {
            throw new IllegalArgumentException("Character buffer is too small. Required at least " + length + " but got " + charBuffer.length + ".");
        }

