                final int byte1 = classFileBuffer[byteIndex++] & 0xFF;

                // Modified UTF-8 to Unicode
                if (byte1 == 0x00) {
                    // Null terminator or explicit null char in modified UTF-8 context? 
                    // MTF-8 nulls are encoded as 0xC0 0x80, while a zero byte at the start of a sequence 
                    // would be invalid. However, within a 1-byte char, 0x00 is NUL.
                    // Let's handle it as a standard 1-byte char.
