                    }
                    final int codePoint = ((byte1 & 0x1F) << 6) | (byte2 & 0x3F);
                    // Modified UTF-8 quirk: 0xC0 0x80 is NUL (0x00) instead of 0xC0 0x80 mapping to U+D800 (surrogate)
                    // Actually, 0xC0 0x80 decodes to 0x00 in standard UTF-8. The quirk is that 2-byte encoding for 
                    // chars < 0x80 is not allowed, but 0xC0 0x80 specifically represents 0x00.
                    // 0xC0 0x80: (0x00 << 6) | 0x00 = 0x00. Standard.
                    // The JVM quirk is that it allows certain surrogates via specific sequences.
                    charBuffer[charIndex++] = (char) codePoint;
