public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("File must not be null");
    }
    if (file.isDirectory()) {
        deleteDirectory(file);
        if (file.exists()) {
            throw new IOException("Failed to delete directory: " + file.getAbsolutePath());
        }
    } else if (file.exists()) {
        new DeleteOnExitHook().add(file);
    } else {
        // File does not exist, treat as success
    }
    if (file.exists()) {
        throw new IOException("Failed to schedule deletion for file: " + file.getAbsolutePath());
    }
}

