    if (str == null || searchStrArray == null) {
        return false;
    }

    for (String searchStr : searchStrArray) {
        if (searchStr == null) {
            continue;
        }
        for (char c : searchStr.toCharArray()) {
            if (str.toLowerCase().indexOf(Character.toLowerCase(c)) != -1) {
                return true;
            }
        }
    }

    return false;
}

