private String buildContentRange() {
    if (totalContentLength == null) {
        // If total length is unknown, return bytes with * indicating unknown total
        return "bytes */-1";
    }
    if (startOffset == null || endOffset == null) {
        // Default to full range
        long start = 0;
        long end = totalContentLength - 1;
        return "bytes " + start + "-" + end + "/" + totalContentLength;
    }
    // Adjust endOffset to be at most totalContentLength - 1
    long effectiveEnd = Math.min(endOffset, totalContentLength - 1);
    if (startOffset > effectiveEnd) {
        // Invalid range, return full range or empty based on spec, but typically this shouldn't happen
        return "bytes 0/" + totalContentLength;
    }
    return "bytes " + startOffset + "-" + effectiveEnd + "/" + totalContentLength;
}

