private static String javaCharset(String charset) {
    if (charset == null || charset.trim().isEmpty()) {
        return "ISO-8859-1"; // Default Java charset or throw exception
    }

    String upper = charset.toUpperCase().trim();
    switch (upper) {
        case "US-ASCII":
        case "ASCII":
            return "US-ASCII";
        case "ISO-8859-1":
        case "LATIN1":
        case "L1":
        case "ISO-8859-1:1987":
            return "ISO-8859-1";
        case "UTF-8":
        case "UTF8":
        case "UTF-8:2003":
            return "UTF-8";
        case "UTF-16":
        case "UNICODE":
        case "UTF-16BE":
            return "UTF-16BE";
        case "UTF-16LE":
            return "UTF-16LE";
        case "UTF-16:2003":
            return "UTF-16";
        default:
            // Try to return the input as-is if it seems valid, otherwise default
            if (charset.length() > 0) {
                return charset;
            }
            return "ISO-8859-1";
    }
}

