private void moveAllListNodes(DoublyLinkedList<E> list) {
    if (list == null || list.isEmpty()) {
        return;
    }
    synchronized (list) {
        synchronized (this) {
            ListNode<E> firstListNode = list.firstListNode;
            if (firstListNode == null) {
                return;
            }
            ListNode<E> lastListNode = list.lastListNode;
            firstListNode.prev = lastListNode;
            lastListNode.next = firstListNode;
            if (firstListNode == lastListNode) {
                // Singleton list
                list.firstListNode = null;
                list.lastListNode = null;
                list.size = 0;
            } else {
                // Multiple nodes
                firstListNode = firstListNode.next;
                lastListNode = lastListNode.prev;
                if (firstListNode == lastListNode) {
                    // Two elements
                    list.firstListNode = null;
                    list.lastListNode = null;
                    list.size = 0;
                } else {
                    // Three or more elements
                    firstListNode.prev = lastListNode;
                    lastListNode.next = firstListNode;
                    list.firstListNode = firstListNode;
                    list.lastListNode = lastListNode;
                    list.size -= 2;
                }
            }
        }
    }
    // Attach this listNodes to current list
    synchronized (this) {
        if (this.size == 0) {
            this.firstListNode = firstListNode;
            this.lastListNode = lastListNode;
        } else {
            ListNode<E> thisFirst = this.firstListNode;
            thisFirst.prev = lastListNode;
            lastListNode.next = thisFirst;
            firstListNode.prev = this.lastListNode;
            this.lastListNode.next = firstListNode;
            this.firstListNode = lastListNode.next;
            this.lastListNode = firstListNode.prev;
        }
        this.size += list.size;
    }
}

