public static <V,E>IsomorphicGraphMapping<V,E> identity(Graph<V,E> graph){
        if (graph == null) {
            throw new IllegalArgumentException("graph must not be null");
        }

        // Check if the graph is a valid graph
        if (!graph.isValid()) {
            throw new IllegalArgumentException("invalid graph");
        }

        // Check if the graph has at least one vertex
        int vertexCount = graph.degreeStream().count();
        if (vertexCount == 0) {
            throw new IllegalArgumentException("graph must have at least one vertex");
        }

        // Check if the graph is simple
        if (!graph.isSimple()) {
            throw new IllegalArgumentException("graph must be simple");
        }

        // Create a mapping from the graph to itself
        IsomorphicGraphMapping<V,E> mapping = new IsomorphicGraphMapping<V,E>() {
            @Override
            public G aimedForEdge(E e) {
                return e;
            }

            @Override
            public V imageOfVertex(V v) {
                return v;
            }

            @Override
            public V sourceOfVertex(V v) {
                return v;
            }

            @Override
            public E edgeImageOfEdge(E e) {
                return e;
            }

            @Override
            public E edgeSourceOfEdge(E e) {
                return e;
            }
        };

        return mapping;
    }

