public void generateGraph(Graph<V,E> target, Map<String, V> resultMap) {
    int leftCount = 0;
    int rightCount = 0;
    List<V> leftPartition = new ArrayList<>();
    List<V> rightPartition = new ArrayList<>();

    // Assume the graph is bipartite with partitions determined by node index
    // For a complete bipartite graph K(m,n), we connect every node in left to every node in right
    V node1 = resultMap.get("A");
    V node2 = resultMap.get("B");

    if (node1 != null && node2 != null) {
        // Determine partition sizes
        Set<V> allNodes = new HashSet<>(resultMap.values());
        List<V> nodes = new ArrayList<>(allNodes);
        leftCount = nodes.size() / 2;
        rightCount = nodes.size() - leftCount;

        for (int i = 0; i < nodes.size(); i++) {
            if (i < leftCount) {
                leftPartition.add(nodes.get(i));
            } else {
                rightPartition.add(nodes.get(i));
            }
        }
    }

    // Add all nodes to the target graph
    for (V node : resultMap.values()) {
        if (!target.containsNode(node)) {
            target.addVertex(node);
        }
    }

    // Connect every node in left partition to every node in right partition
    for (V leftNode : leftPartition) {
        for (V rightNode : rightPartition) {
            if (!target.containsEdge(leftNode, rightNode)) {
                target.addEdge(leftNode, rightNode, leftNode + "-" + rightNode);
            }
        }
    }
}

