    public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
        try {
            // Get the number of vertices from the configuration
            int numVerticesA = Integer.parseInt(config.get("numVerticesA"));
            int numVerticesB = Integer.parseInt(config.get("numVerticesB"));

            // Clear existing vertices and edges
            target.clear();

