private int computeBinaryLog(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer");
    }

    // Check if n is a power of 2
    // If n is a power of 2, return the exact value: log2(n) + 1
    // Otherwise, return floor(log2(n)) + 1

    // For exact powers of 2: n & (n - 1) == 0
    if ((n & (n - 1)) == 0) {
        return Integer.numberOfTrailingZeros(n) + 1;
    }

    // For non-powers of 2: floor(log2(n)) is the number of bits - 1
    // So floor(log2(n)) + 1 = number of bits
    return Integer.SIZE - Integer.numberOfLeadingZeros(n);
}

