private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
        OuterFaceCirculator circulator = new OuterFaceCirculator(start, dir);
        Node current = start;

        // If the start node satisfies the predicate or is the stop node, return it
        if (current == stop || predicate.test(current)) {
            return circulator;
        }

        // Start traversing from the next node
        circulator.setDir(dir);
        while (true) {
            circulator.setNode(circulator.next());
            current = circulator.getNode();

            if (current == stop || predicate.test(current)) {
                break;
            }

            // Prevent infinite loop if we come back to start without finding the predicate
            if (current == start) {
                break;
            }
        }

        return circulator;
    }

