protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || tour.isEmpty()) {
        return null;
    }
    if (graph == null) {
        return null;
    }

    // Gather all vertices involved in the tour
    Set<V> vertices = new HashSet<>();
    for (E edge : tour) {
        vertices.add(graph.getEdgeSource(edge));
        vertices.add(graph.getEdgeTarget(edge));
    }

    // Build an adjacency map for the tour edges
    Map<V, List<Pair<V,E>>> adj = new HashMap<>();
    for (E edge : tour) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);
        adj.computeIfAbsent(source, k -> new ArrayList<>()).add(new Pair<>(target, edge));
        adj.computeIfAbsent(target, k -> new ArrayList<>()).add(new Pair<>(source, edge));
    }

    // Find a starting vertex with odd degree or any vertex if all even
    V start = null;
    for (V v : vertices) {
        List<Pair<V,E>> neighbors = adj.get(v);
        if (neighbors == null || neighbors.size() % 2 != 0) {
            start = v;
            break;
        }
    }
    if (start == null && !vertices.isEmpty()) {
        start = vertices.iterator().next();
    }
    if (start == null) {
        return null;
    }

    // Use Hierholzer's algorithm to find the Eulerian circuit/path
    Deque<V> stack = new LinkedList<>();
    Deque<E> pathEdges = new LinkedList<>();
    List<V> pathVertices = new ArrayList<>();

    stack.push(start);
    while (!stack.isEmpty()) {
        V current = stack.peek();
        List<Pair<V,E>> neighbors = adj.get(current);

        // Find an unused edge
        while (neighbors != null && !neighbors.isEmpty()) {
            Pair<V,E> pair = neighbors.remove(neighbors.size() - 1);
            if (!pathEdges.contains(pair.getB())) {
                pathEdges.addFirst(pair.getB());
                stack.push(pair.getA());
                break;
            }
        }

        // If no unused edges from current vertex, add it to path and backtrack
        if (neighbors == null || neighbors.isEmpty()) {
            pathVertices.addFirst(stack.pop());
        }
    }

    // Build the final path
    if (pathVertices.isEmpty()) {
        return null;
    }

    List<V> finalVertices = pathVertices;
    List<E> finalEdges = new ArrayList<>(tour.size());
    for (int i = 0; i < finalVertices.size() - 1; i++) {
        V v1 = finalVertices.get(i);
        V v2 = finalVertices.get(i + 1);
        E edge = graph.getEdge(v1, v2);
        if (edge != null && tour.contains(edge)) {
            finalEdges.add(edge);
        }
    }

    return new GraphPath<>(graph, finalVertices, finalEdges);
}

