public static String capitalize(String name) {
    if (name == null || name.isEmpty()) {
        return name;
    }

    char[] chars = name.toCharArray();
    int i = 0;

    // Handle case like "URLConnection" - skip the first uppercase letter and find where lowercase starts
    while (i < chars.length && Character.isUpperCase(chars[i])) {
        i++;
    }

    // If all characters are uppercase, or only one uppercase letter at start, just capitalize the first letter
    if (i == 0 || i == chars.length) {
        chars[0] = Character.toUpperCase(chars[0]);
    } else {
        // Reverse of decapitalize: if the first two characters are uppercase, leave as is.
        // Otherwise, capitalize the first character.
        if (chars[0] != Character.toUpperCase(chars[0])) {
            chars[0] = Character.toUpperCase(chars[0]);
        }
    }

    return new String(chars);
}

