public Action inspect(AtmosphereResource r) {
    try {
        if (r != null) {
            AtmosphereResource.TRANSPORT transport = r.transport();

            if (transport == AtmosphereResource.TRANSPORT.COMET) {
                r.suspend(Long.MAX_VALUE, TimeUnit.MILLISECONDS);
            } else if (transport == AtmosphereResource.TRANSPORT.WEBSOCKET) {
                r.suspend(Long.MAX_VALUE, TimeUnit.MILLISECONDS);
            } else if (transport == AtmosphereResource.TRANSPORT.LONG_POLLING) {
                // For long polling, the resource is handled by Atmosphere core
                // No explicit suspend needed here, or suspend with a timeout if desired
                // This depends on the specific framework implementation, but typically 
                // long polling is suspended by the client reconnecting or by timeout
                // For consistency, we might just continue
            } else {
                // Other transports (SSE, etc.) might need handling
                r.suspend(Long.MAX_VALUE, TimeUnit.MILLISECONDS);
            }
        }
    } catch (Exception e) {
        // Log the exception or handle it as required by the framework
    }
    return Action.CONTINUE;
}

