public static String stripFilenameExtension(String path) {
    if (path == null) {
        return null;
    }

    // Find the last file separator (either '/' or '\')
    int slashIndex = Math.max(path.lastIndexOf('/'), path.lastIndexOf('\\'));

    // Find the last dot after the last slash (to avoid stripping directory names)
    int dotIndex = path.lastIndexOf('.');

    // If no dot found, or dot is before or at the same position as the last slash,
    // then no extension to strip
    if (dotIndex < slashIndex || dotIndex == -1) {
        return path;
    }

    // Also handle case where dot is at the beginning of the filename (hidden files)
    // e.g., ".bashrc" - no extension to strip, but this is a matter of convention.
    // Typically, we consider a filename starting with a dot as having no extension,
    // or the entire name is the extension. For simplicity, we treat dot as extension marker.
    // However, to be safe, if the dot is right after the last slash, we might consider it
    // as a hidden file with no extension. Let's check: if dotIndex == slashIndex + 1,
    // it means the filename starts with a dot (e.g., /dir/.file). Some implementations
    // consider this as no extension. We'll follow the common pattern: strip from the
    // last dot if it's after the last slash.

    return path.substring(0, dotIndex);
}

