        // If packed, we should have already set the packed fields flag in the field descriptor
        if (fieldDescriptor.isPacked()) {
            readPackedNumericField(fieldDescriptor.getType());
        } else {
            // Update internal state to reflect that we are reading a packed field
            // Actually, for length-delimited fields, we need to parse the length and content
            int length = readVarint32();
            byte[] data = new byte[length];
            readRawBytes(data);
            // Process the data based on the field type
            switch (fieldDescriptor.getType()) {
                case FIXED64:
                    // Fixed64 packed fields are sequences of 8-byte values
                    if (length % 8 != 0) {
                        throw new IOException("Invalid packed field length");
                    }
                    for (int i = 0; i < length; i += 8) {
                        long value = ByteBuffer.wrap(data, i, 8).order(ByteOrder.LITTLE_ENDIAN).getLong();
                        // Add value to packed field values
                        // For simplicity, we assume the field values are stored in a list
                        // In actual implementation, we would add to the appropriate field storage
                    }
                    break;
                case FLOAT:
                    // Float packed fields are sequences of 4-byte values
                    if (length % 4 != 0) {
                        throw new IOException("Invalid packed field length");
                    }
                    for (int i = 0; i < length; i += 4) {
                        float value = ByteBuffer.wrap(data, i, 4).order(ByteOrder.LITTLE_ENDIAN).getFloat();
                        // Add value to packed field values
                    }
                    break;
                case DOUBLE:
                    // Double packed fields are sequences of 8-byte values
                    if (length % 8 != 0) {
                        throw new IOException("Invalid packed field length");
                    }
                    for (int i = 0; i < length; i += 8) {
                        double value = ByteBuffer.wrap(data, i, 8).order(ByteOrder.LITTLE_ENDIAN).getDouble();
                        // Add value to packed field values
                    }
                    break;
                case FIXED32:
                    // Fixed32 packed fields are sequences of 4-byte values
                    if (length % 4 != 0) {
                        throw new IOException("Invalid packed field length");
                    }
                    for (int i = 0; i < length; i += 4) {
                        int value = ByteBuffer.wrap(data, i, 4).order(ByteOrder.LITTLE_ENDIAN).getInt();
                        // Add value to packed field values
                    }
                    break;
                case SINT32:
                case INT32:
                case SINT64:
                case INT64:
